CREATE COLUMN TABLE "TEST_AP"."ODPV" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50) NOT NULL , "DprArea" NVARCHAR(15) NOT NULL , "PeriodCat" NVARCHAR(10) NOT NULL , "FromDate" LONGDATE CS_LONGDATE, "ToDate" LONGDATE CS_LONGDATE, "OrdDprPlan" DECIMAL(21,6) CS_FIXED, "OrdDprPost" DECIMAL(21,6) CS_FIXED, "OrdDprAct" DECIMAL(21,6) CS_FIXED, "SpDprKey" NVARCHAR(2), "SpDprPlan" DECIMAL(21,6) CS_FIXED, "SpDprPost" DECIMAL(21,6) CS_FIXED, "SpDprAct" DECIMAL(21,6) CS_FIXED, "SubPeriod" INTEGER CS_INT NOT NULL , "OrdDprPln1" DECIMAL(21,6) CS_FIXED, "OrdDprPst1" DECIMAL(21,6) CS_FIXED, "OrdDprAct1" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ODPV_SECONDARY" ON "TEST_AP"."ODPV" ( "ItemCode" ASC, "DprArea" ASC, "PeriodCat" ASC, "SubPeriod" ASC )